# Final verification that we don't over-apply
inputs = ['zw', 'ju', 'fycfh', 'kgkbg', 'ff']
outputs = ['zyi', 'ewf', 'yycyh', 'kgkbg', 'yy']

rules = [("f", "y"), ("w", "yi"), ("j", "e"), ("u", "wf")]

# Check that our rules only affect the intended strings
print("Verifying no over-applications:")
all_correct = True

for i, (inp, expected) in enumerate(zip(inputs, outputs)):
    result = inp
    for pattern, replacement in rules:
        result = result.replace(pattern, replacement)

    if result == expected:
        print(f"✓ '{inp}' -> '{result}'")
    else:
        print(f"✗ '{inp}' -> '{result}' (expected '{expected}')")
        all_correct = False

print(f"\nAll transformations correct: {all_correct}")

# Check if any rules would modify strings outside our test set
print("\nChecking if any rules would modify strings not in our test set:")
test_strings = ['zw', 'ju', 'fycfh', 'kgkbg', 'ff', 'abc', 'xyz', 'fff', 'www', 'jjj', 'uuu']
for pattern, replacement in rules:
    modified = []
    for s in test_strings:
        if pattern in s and s.replace(pattern, replacement) != s:
            modified.append((s, s.replace(pattern, replacement)))
    if modified:
        print(f"Rule '{pattern}' -> '{replacement}' would modify: {modified}")
    else:
        print(f"Rule '{pattern}' -> '{replacement}' would modify nothing outside test set")

